def _run_selftest() -> int:
    """Compact dependency-free sanity checks for filtering and ranking."""
    docs = build_demo_corpus()
    pipe = RAGPipeline.from_documents(docs)
    store, ranker = pipe.store, pipe.ranker

    # --- metadata filtering ------------------------------------------------
    ids = store.filter_candidate_ids({"category": "api"})
    assert ids, "eq filter returned nothing"
    assert all(store.chunks[i].metadata["category"] == "api" for i in ids)

    ids = store.filter_candidate_ids({"category": {"in": ["api", "billing"]}})
    cats = {store.chunks[i].metadata["category"] for i in ids}
    assert cats <= {"api", "billing"} and "api" in cats, "in filter failed"

    ids = store.filter_candidate_ids({"date": {"gte": "2024-06-01"}})
    assert all(_coerce_date(store.chunks[i].metadata["date"]) >= datetime(2024, 6, 1) for i in ids)

    ids = store.filter_candidate_ids({"tags": {"contains": "security"}})
    assert all("security" in store.chunks[i].metadata["tags"] for i in ids)

    ids = store.filter_candidate_ids({"status": "draft"})
    assert all(store.chunks[i].metadata["status"] == "draft" for i in ids)

    ids = store.filter_candidate_ids({"missing_field": {"exists": False}})
    assert len(ids) == len(store.chunks), "exists:false should match all"

    # --- ranking -----------------------------------------------------------
    ranked = pipe.retrieve(
        "How do I raise the API rate limit?",
        k=3,
        filters={"category": {"in": ["api", "support"]}},
    )
    assert ranked and ranked[0].rank == 1
    titles = [r.metadata["title"] for r in ranked]
    assert "API rate limits" in titles, f"expected rate-limit doc, got {titles}"

    # preference for security must promote the security doc
    ranked_sec = pipe.retrieve(
        "How do I raise the API rate limit?",
        k=8,
        prefer={"category": "security"},
    )
    sec_rank = next(
        (r.rank for r in ranked_sec if r.metadata["category"] == "security"), None
    )
    assert sec_rank is not None and sec_rank <= 3, f"prefer failed, sec_rank={sec_rank}"

    # no matches -> graceful empty answer
    empty = pipe.answer("nonsense query zzz", filters={"category": "does-not-exist"})
    assert empty.sources == [] and "No documents matched" in empty.answer

    print(f"selftest OK: {len(docs)} docs, {len(store.chunks)} chunks")
    return 0


def main(argv: Optional[List[str]] = None) -> int:
    parser = argparse.ArgumentParser(
        description="Metadata-aware RAG demo",
        formatter_class=argparse.ArgumentDefaultsHelpFormatter,
    )
    parser.add_argument("--query", help="question to ask")
    parser.add_argument("--k", type=int, default=5, help="number of chunks to return")
    parser.add_argument(
        "--filters",
        help='JSON metadata filters, e.g. \'{"category": "api"}\'',
    )
    parser.add_argument(
        "--prefer",
        help='JSON metadata preferences, e.g. \'{"category": "api"}\'',
    )
    parser.add_argument("--mmr", action="store_true", help="enable MMR diversity")
    parser.add_argument(
        "--no-generate", action="store_true", help="print retrieved chunks instead of an answer"
    )
    parser.add_argument("--json", action="store_true", help="emit JSON response")
    parser.add_argument(
        "--use-openai",
        action="store_true",
        help="use OpenAI-compatible generator if OPENAI_API_KEY is set",
    )
    parser.add_argument("--list", action="store_true", help="show demo documents and exit")
    parser.add_argument("--selftest", action="store_true", help="run sanity checks and exit")
    args = parser.parse_args(argv)

    if args.selftest:
        return _run_selftest()

    docs = build_demo_corpus()
    if args.list:
        for d in docs:
            meta = d.metadata
            print(
                f"- {meta['title']:32s} cat={meta['category']:12s} "
                f"date={meta['date']} tags={','.join(meta['tags'])} "
                f"status={meta['status']}"
            )
        return 0

    config = RankingConfig(use_mmr=args.mmr)
    generator = OpenAICompatibleGenerator() if args.use_openai else None
    pipe = RAGPipeline.from_documents(docs, ranking_config=config, generator=generator)

    filters = json.loads(args.filters) if args.filters else None
    prefer = json.loads(args.prefer) if args.prefer else None

    if args.query:
        queries = [args.query]
    else:
        queries = [q for q, _, _ in EXAMPLE_QUERIES]

    for q in queries:
        resp = pipe.answer(
            q, k=args.k, filters=filters, prefer=prefer, generate=not args.no_generate
        )
        if args.json:
            print(json.dumps(resp.to_dict(), indent=2))
            continue
        print(f"\nQ: {q}")
        if filters:
            print(f"   filters: {filters}")
        if prefer:
            print(f"   prefer:  {prefer}")
        print(
            f"A [{resp.generation_method}] ({resp.elapsed_seconds:.2f}s): {resp.answer}"
        )
        print("Sources:")
        for s in resp.sources:
            print(
                f"   #{s.rank} score={s.final_score:.3f} "
                f"(sim={s.similarity:.3f} kw={s.keyword_score:.3f} "
                f"meta={s.metadata_score:.3f}) "
                f"{s.metadata.get('title', '?')} [{s.chunk.chunk_id}]"
            )
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""Scoring algorithms: TF-IDF, BM25, hybrid fusion, MMR, and reranking."""
from __future__ import annotations

import math
from collections import Counter
from typing import Callable, Dict, List, Optional, Sequence, Tuple


class TFIDFIndex:
    """Sparse TF-IDF vectors with L2 normalization; cosine = dot product."""

    def __init__(self) -> None:
        self.vectors: List[Dict[str, float]] = []
        self.doc_freq: Counter = Counter()
        self.idf: Dict[str, float] = {}
        self.n_docs = 0

    def build(self, tokenized_docs: Sequence[Sequence[str]]) -> None:
        self.n_docs = len(tokenized_docs)
        for tokens in tokenized_docs:
            for term in set(tokens):
                self.doc_freq[term] += 1
        for term, df in self.doc_freq.items():
            self.idf[term] = math.log((self.n_docs + 1) / (df + 1)) + 1.0
        self.vectors = [self._vector(tokens) for tokens in tokenized_docs]

    def _vector(self, tokens: Sequence[str]) -> Dict[str, float]:
        counts = Counter(tokens)
        vec = {t: (1.0 + math.log(tf)) * self.idf.get(t, 1.0) for t, tf in counts.items()}
        norm = math.sqrt(sum(w * w for w in vec.values())) or 1.0
        return {t: w / norm for t, w in vec.items()}

    def query_vector(self, tokens: Sequence[str]) -> Dict[str, float]:
        return self._vector(tokens)

    def score(self, doc_index: int, query_vec: Dict[str, float]) -> float:
        doc_vec = self.vectors[doc_index]
        if len(doc_vec) > len(query_vec):  # iterate over the smaller vector
            doc_vec, query_vec = query_vec, doc_vec
        total = 0.0
        for term, w in query_vec.items():
            if term in doc_vec:
                total += w * doc_vec[term]
        return total


class BM25Index:
    """Classic Okapi BM25 sparse retrieval."""

    K1 = 1.5
    B = 0.75

    def __init__(self) -> None:
        self.doc_lens: List[int] = []
        self.avgdl = 0.0
        self.n_docs = 0
        self.postings: Dict[str, Dict[int, int]] = {}
        self.doc_freq: Counter = Counter()

    def build(self, tokenized_docs: Sequence[Sequence[str]]) -> None:
        self.n_docs = len(tokenized_docs)
        self.doc_lens = [len(t) for t in tokenized_docs]
        self.avgdl = (sum(self.doc_lens) / self.n_docs) if self.n_docs else 0.0
        for idx, tokens in enumerate(tokenized_docs):
            for term, tf in Counter(tokens).items():
                self.postings.setdefault(term, {})[idx] = tf
                self.doc_freq[term] += 1

    def score(self, doc_index: int, query_tokens: Sequence[str]) -> float:
        dl = self.doc_lens[doc_index]
        score = 0.0
        for term in set(query_tokens):
            df = self.doc_freq.get(term, 0)
            if df == 0:
                continue
            idf = math.log(1.0 + (self.n_docs - df + 0.5) / (df + 0.5))
            tf = self.postings[term].get(doc_index, 0)
            if tf == 0:
                continue
            if self.avgdl:
                denom = tf + self.K1 * (1.0 - self.B + self.B * dl / self.avgdl)
            else:
                denom = tf + self.K1
            score += idf * (tf * (self.K1 + 1.0)) / denom
        return score


def minmax_normalize(scores: Dict[str, float]) -> Dict[str, float]:
    """Scale a method's raw scores to [0, 1] across the candidate set."""
    if not scores:
        return {}
    lo = min(scores.values())
    hi = max(scores.values())
    if hi - lo < 1e-12:
        return {k: 1.0 for k in scores}
    return {k: (v - lo) / (hi - lo) for k, v in scores.items()}


def combine_scores(
    scores_by_method: Dict[str, Dict[str, float]],
    weights: Optional[Sequence[float]] = None,
    strategy: str = "minmax",
) -> Dict[str, float]:
    """Fuse per-method relevance scores.

    strategy='minmax': min-max normalize each method, then weighted sum.
    strategy='rrf'   : Reciprocal Rank Fusion over each method's ranking.
    """
    methods = list(scores_by_method.keys())
    if not methods:
        return {}
    w = {
        m: (float(weights[i]) if weights and i < len(weights) else 1.0 / len(methods))
        for i, m in enumerate(methods)
    }
    total_w = sum(w.values()) or 1.0
    w = {m: v / total_w for m, v in w.items()}

    if strategy == "rrf":
        fused: Dict[str, float] = {}
        for m in methods:
            ranked = sorted(scores_by_method[m].items(), key=lambda kv: kv[1], reverse=True)
            for rank, (doc, _) in enumerate(ranked, start=1):
                fused[doc] = fused.get(doc, 0.0) + w[m] / (60.0 + rank)
        return fused

    normalized = {m: minmax_normalize(scores_by_method[m]) for m in methods}
    all_docs = set()
    for s in normalized.values():
        all_docs |= set(s.keys())
    fused: Dict[str, float] = {}
    for doc in all_docs:
        fused[doc] = sum(normalized[m].get(doc, 0.0) * w[m] for m in methods)
    return fused


def mmr_select(
    candidates: Sequence[Tuple[str, float]],
    similarity: Callable[[str, str], float],
    k: int,
    lam: float = 0.5,
) -> List[Tuple[str, float]]:
    """Maximal Marginal Relevance: greedily pick items that are relevant (score)
    yet dissimilar to already-selected items. lambda=1 -> pure relevance,
    lambda=0 -> pure diversity."""
    if not candidates:
        return []
    selected: List[Tuple[str, float]] = []
    remaining = list(candidates)
    while remaining and len(selected) < k:
        best_idx = 0
        best_score = -math.inf
        for i, (doc, rel) in enumerate(remaining):
            sim_max = max((similarity(doc, s_doc) for s_doc, _ in selected), default=0.0)
            mmr = lam * rel - (1.0 - lam) * sim_max
            if mmr > best_score:
                best_score = mmr
                best_idx = i
        selected.append(remaining.pop(best_idx))
    return selected


class QueryTermReranker:
    """Lightweight second-stage reranker: blends the retrieval score with the
    idf-weighted query-term coverage of the document. This is a stand-in for a
    cross-encoder reranker; swap for one (e.g. ms-marco-MiniLM) in production."""

    def __init__(self, idf: Dict[str, float], alpha: float = 0.6) -> None:
        self.idf = idf
        self.alpha = alpha

    def score(self, query_tokens: Sequence[str], doc_tokens: Sequence[str], base_score: float) -> float:
        q = list(dict.fromkeys(query_tokens))
        if not q:
            return base_score
        total = sum(self.idf.get(t, 1.0) for t in q) or 1.0
        doc_set = set(doc_tokens)
        coverage = sum(self.idf.get(t, 1.0) for t in q if t in doc_set) / total
        return self.alpha * base_score + (1.0 - self.alpha) * coverage

"""Metadata filtering engine and in-memory vector store."""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional

OPERATORS = frozenset(
    {"$eq", "$neq", "$in", "$nin", "$contains", "$exists", "$gt", "$gte", "$lt", "$lte"}
)


@dataclass
class Chunk:
    """A retrievable unit: text, tokens, TF-IDF vector, and metadata."""

    id: str
    text: str
    metadata: Dict[str, Any]
    tokens: List[str]
    vector: Dict[str, float] = field(default_factory=dict)
    length: int = 0

    def __post_init__(self) -> None:
        if not self.length:
            self.length = len(self.tokens)


def _compare(value: Any, op: str, expected: Any) -> bool:
    if op == "$eq":
        return value == expected
    if op == "$neq":
        return value != expected
    if op == "$in":
        if value is None:
            return False
        if isinstance(value, (list, tuple, set)):
            return any(v in expected for v in value)
        return value in expected
    if op == "$nin":
        if value is None:
            return True
        if isinstance(value, (list, tuple, set)):
            return not any(v in expected for v in value)
        return value not in expected
    if op == "$contains":
        if value is None:
            return False
        if isinstance(value, (list, tuple, set)):
            return all(item in value for item in expected)
        if isinstance(value, str):
            return expected in value
        return False
    if op == "$exists":
        return (value is not None) == bool(expected)
    if op in ("$gt", "$gte", "$lt", "$lte"):
        if value is None:
            return False
        try:
            if op == "$gt":
                return value > expected
            if op == "$gte":
                return value >= expected
            if op == "$lt":
                return value < expected
            return value <= expected
        except TypeError:
            return False
    return False


def matches(metadata: Dict[str, Any], filters: Optional[Dict[str, Any]]) -> bool:
    """Evaluate a MongoDB-style filter against a metadata dict.

    Supported:
      {'field': value}                         equality (and implicit AND of fields)
      {'field': {'$eq'|'$neq'|'$in'|'$nin'|'$contains'|'$exists'|'$gt'|'$gte'|'$lt'|'$lte': v}}
      {'$or': [filter, ...]} / {'$and': [...]} / {'$not': filter}
    """
    if not filters:
        return True
    if "$or" in filters:
        return any(matches(metadata, cond) for cond in filters["$or"])
    if "$and" in filters:
        return all(matches(metadata, cond) for cond in filters["$and"])
    if "$not" in filters:
        return not matches(metadata, filters["$not"])

    for field, spec in filters.items():
        if field.startswith("$"):
            continue
        if isinstance(spec, dict) and any(k in OPERATORS for k in spec):
            for op, expected in spec.items():
                if not _compare(metadata.get(field), op, expected):
                    return False
        elif spec is not None:
            if metadata.get(field) != spec:
                return False
        else:  # explicit null check
            if field not in metadata or metadata[field] is None:
                return False
    return True


class VectorStore:
    """In-memory store of chunks with metadata filter + cosine similarity support."""

    def __init__(self) -> None:
        self._chunks: Dict[str, Chunk] = {}
        self._order: List[str] = []

    def add(self, chunk: Chunk) -> None:
        self._chunks[chunk.id] = chunk
        self._order.append(chunk.id)

    def get(self, cid: str) -> Optional[Chunk]:
        return self._chunks.get(cid)

    def all(self) -> List[Chunk]:
        return [self._chunks[cid] for cid in self._order]

    def size(self) -> int:
        return len(self._order)

    def ids_matching(self, filters: Optional[Dict[str, Any]]) -> List[str]:
        if not filters:
            return list(self._order)
        return [cid for cid in self._order if matches(self._chunks[cid].metadata, filters)]

    def cosine(self, a_id: str, b_id: str) -> float:
        va = self._chunks[a_id].vector
        vb = self._chunks[b_id].vector
        if not va or not vb:
            return 0.0
        if len(va) > len(vb):
            va, vb = vb, va
        return sum(w * vb.get(t, 0.0) for t, w in va.items())

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
MetadataAwareRAG
================

A self-contained Retrieval-Augmented Generation (RAG) system that uses
document *metadata* for both **filtering** and **ranking** documents by
relevance to a user query.

Pipeline
--------
1. **Ingest** – documents arrive as ``Document(text, metadata)`` where
   ``metadata`` is an arbitrary JSON-compatible mapping (title, category,
   author, date, tags, priority, ...).
2. **Chunk** – text is split into overlapping chunks by
   :class:`RecursiveChunker`.
3. **Embed** – chunks are embedded by a pluggable embedder. Two
   dependency-free embedders ship with the module:
   :class:`HashedNGramEmbedder` (dense) and :class:`TfidfEmbedder`
   (sparse). Any callable returning a vector (list of floats or dict of
   weights) can be supplied instead, e.g. sentence-transformers or an
   OpenAI-compatible embedding endpoint.
4. **Store** – chunk vectors and metadata live in
   :class:`MetadataVectorStore`.
5. **Filter** – :meth:`MetadataVectorStore.search` accepts a ``filters``
   mapping (equality, ``in``/``nin``, ``gt``/``gte``/``lt``/``lte``,
   ``contains``, ``range``, ``exists``, ``regex``) evaluated against chunk
   metadata *before* any scoring.
6. **Rank** – :class:`RelevanceRanker` blends
     - semantic similarity (cosine between query and chunk embeddings),
     - keyword coverage (query-token overlap in the chunk text),
     - metadata relevance (recency decay on ``date``, explicit numeric
       ``boost`` multipliers, and query-declared metadata preferences such
       as ``prefer={"category": "api"}``),
   then optionally applies Maximal Marginal Relevance for diversity.
7. **Generate** – :class:`RAGPipeline.answer` feeds the top-ranked chunks
   to a generator (OpenAI-compatible chat endpoint, with a dependency-free
   extractive fallback) and returns a :class:`RAGResponse` with citations.

The module is pure Python-standard-library; optional integrations activate
only when their dependencies are present.

Quick start
-----------
.. code-block:: python

    from rag_metadata_system import RAGPipeline, build_demo_corpus

    pipe = RAGPipeline.from_documents(build_demo_corpus())
    resp = pipe.answer(
        "How do we rate-limit the public API?",
        filters={"category": {"in": ["api", "security"]}},
        prefer={"category": "api"},
        k=5,
    )
    print(resp.answer)
    for src in resp.sources:
        print(f"  [{src.rank}] {src.metadata['title']}  score={src.final_score:.3f}")

Command line
------------
    python rag_metadata_system.py --query "rate limiting" --k 5 \
        --filters '{"category": {"in": ["api", "security"]}}' \
        --prefer '{"category": "api"}'
    python rag_metadata_system.py --list
    python rag_metadata_system.py --selftest
"""

