# ---------------------------------------------------------------------------
# Data containers
# ---------------------------------------------------------------------------


@dataclass
class Document:
    """A source document: free text plus structured metadata."""

    text: str
    metadata: Dict[str, Any] = field(default_factory=dict)
    doc_id: Optional[str] = None

    def __post_init__(self) -> None:
        if self.doc_id is None:
            self.doc_id = hashlib.md5(self.text[:4096].encode("utf-8")).hexdigest()[:12]

    def to_dict(self) -> Dict[str, Any]:
        return {"doc_id": self.doc_id, "metadata": dict(self.metadata), "text": self.text}


@dataclass
class Chunk:
    """A chunk of a document, carrying inherited metadata."""

    text: str
    metadata: Dict[str, Any]
    doc_id: str
    index: int
    chunk_id: str = ""

    def __post_init__(self) -> None:
        if not self.chunk_id:
            self.chunk_id = f"{self.doc_id}:{self.index}"


@dataclass
class RetrievalResult:
    """A candidate chunk surfaced by the vector store."""

    chunk: Chunk
    similarity: float  # raw semantic similarity, 0..1


@dataclass
class RankedResult:
    """A chunk after metadata-aware relevance ranking."""

    chunk: Chunk
    similarity: float
    keyword_score: float
    metadata_score: float
    final_score: float
    rank: int = 0

    @property
    def metadata(self) -> Dict[str, Any]:
        return self.chunk.metadata


@dataclass
class RAGResponse:
    """The outcome of a full RAG query."""

    query: str
    answer: str
    sources: List[RankedResult]
    filters: Dict[str, Any] = field(default_factory=dict)
    elapsed_seconds: float = 0.0
    generation_method: str = ""

    def to_dict(self) -> Dict[str, Any]:
        return {
            "query": self.query,
            "answer": self.answer,
            "generation_method": self.generation_method,
            "elapsed_seconds": round(self.elapsed_seconds, 4),
            "filters": self.filters,
            "sources": [
                {
                    "rank": s.rank,
                    "score": round(s.final_score, 4),
                    "similarity": round(s.similarity, 4),
                    "keyword": round(s.keyword_score, 4),
                    "metadata": round(s.metadata_score, 4),
                    "chunk_id": s.chunk.chunk_id,
                    "doc_id": s.chunk.doc_id,
                    "metadata": s.chunk.metadata,
                    "text": s.chunk.text,
                }
                for s in self.sources
            ],
        }


# ---------------------------------------------------------------------------
# Chunking
# ---------------------------------------------------------------------------


class RecursiveChunker:
    """Sentence-aware chunker producing overlapping chunks.

    Chunks never exceed ``chunk_size`` characters; every new chunk carries
    the tail of the previous chunk (``chunk_overlap`` characters) so that
    context at boundaries is preserved.
    """

    _SENTENCE_RE = re.compile(r"(?<=[.!?])\s+|\n+")

    def __init__(self, chunk_size: int = 1000, chunk_overlap: int = 150) -> None:
        if chunk_size <= 0:
            raise ValueError("chunk_size must be positive")
        if chunk_overlap < 0 or chunk_overlap >= chunk_size:
            raise ValueError("chunk_overlap must be in [0, chunk_size)")
        self.chunk_size = chunk_size
        self.chunk_overlap = chunk_overlap

    def split(self, text: str) -> List[str]:
        """Split ``text`` into overlapping chunks."""
        text = re.sub(r"\s+", " ", text).strip()
        if not text:
            return []
        pieces = [p.strip() for p in self._SENTENCE_RE.split(text) if p.strip()]
        chunks: List[str] = []
        current = ""
        for piece in pieces:
            if not current:
                current = piece
            elif len(current) + 1 + len(piece) <= self.chunk_size:
                current = f"{current} {piece}"
            else:
                chunks.append(current)
                overlap = (
                    current[-self.chunk_overlap :].strip() if self.chunk_overlap else ""
                )
                current = f"{overlap} {piece}".strip()
                # A single piece longer than the chunk size is hard-cut.
                while len(current) > self.chunk_size:
                    cut = current[: self.chunk_size].rstrip()
                    chunks.append(cut)
                    if self.chunk_overlap:
                        current = current[len(cut) - self.chunk_overlap :]
                    else:
                        current = current[len(cut) :]
        if current:
            chunks.append(current)
        return chunks


def chunk_documents(
    documents: Iterable[Document], chunker: RecursiveChunker
) -> List[Chunk]:
    """Chunk documents, inheriting document metadata into each chunk."""
    out: List[Chunk] = []
    for doc in documents:
        for i, text in enumerate(chunker.split(doc.text)):
            meta = dict(doc.metadata)
            meta.setdefault("doc_id", doc.doc_id)
            meta.setdefault("chunk_index", i)
            out.append(
                Chunk(
                    text=text,
                    metadata=meta,
                    doc_id=doc.doc_id or "",
                    index=i,
                )
            )
    return out


# ---------------------------------------------------------------------------
# Embeddings
# ---------------------------------------------------------------------------

Vector = Any  # List[float] (dense) or Dict[str, float] (sparse)


def _l2_norm(vec: Vector) -> float:
    if isinstance(vec, dict):
        return math.sqrt(sum(v * v for v in vec.values()))
    return math.sqrt(sum(x * x for x in vec))


def l2_normalize(vec: Vector) -> Vector:
    """L2-normalise a dense list or sparse dict vector in place-safe way."""
    norm = _l2_norm(vec)
    if norm == 0.0:
        return dict(vec) if isinstance(vec, dict) else list(vec)
    if isinstance(vec, dict):
        return {k: v / norm for k, v in vec.items()}
    return [x / norm for x in vec]


def cosine_similarity(a: Vector, b: Vector) -> float:
    """Cosine similarity supporting dense (list) and sparse (dict) vectors."""
    if isinstance(a, dict) and isinstance(b, dict):
        if not a or not b:
            return 0.0
        smaller, larger = (a, b) if len(a) <= len(b) else (b, a)
        dot = sum(weight * larger.get(key, 0.0) for key, weight in smaller.items())
        na, nb = _l2_norm(a), _l2_norm(b)
        return dot / (na * nb) if na and nb else 0.0
    if not a or not b or len(a) != len(b):
        return 0.0
    dot = sum(x * y for x, y in zip(a, b))
    na, nb = _l2_norm(a), _l2_norm(b)
    return dot / (na * nb) if na and nb else 0.0


class HashedNGramEmbedder:
    """Dependency-free dense embedder.

    Text is tokenised into lowercase word n-grams, each hashed into a
    fixed-dimension count vector (with a sign trick to reduce collisions),
    then L2-normalised. Deterministic across processes (uses MD5, not
    Python's salted ``hash``).
    """

    _TOKEN_RE = re.compile(r"[a-z0-9]+")

    def __init__(self, dim: int = 512, ngram_range: Tuple[int, int] = (1, 2)) -> None:
        if ngram_range[0] < 1 or ngram_range[1] < ngram_range[0]:
            raise ValueError("invalid ngram_range")
        self.dim = dim
        self.ngram_range = ngram_range

    def tokens(self, text: str) -> List[str]:
        return self._TOKEN_RE.findall(text.lower())

    def embed(self, text: str) -> List[float]:
        vec = [0.0] * self.dim
        toks = self.tokens(text)
        for n in range(self.ngram_range[0], self.ngram_range[1] + 1):
            for i in range(len(toks) - n + 1):
                gram = " ".join(toks[i : i + n])
                digest = hashlib.md5(gram.encode("utf-8")).digest()
                idx = int.from_bytes(digest[:4], "little") % self.dim
                sign = 1.0 if digest[4] & 1 else -1.0
                vec[idx] += sign
        return l2_normalize(vec)  # type: ignore[return-value]


class TfidfEmbedder:
    """Sparse TF-IDF embedder fitted on a corpus.

    Produces ``{term: weight}`` dicts; similarity is cosine over the shared
    vocabulary, complementing keyword-style relevance.
    """

    def __init__(self, min_df: int = 1, smooth_idf: bool = True) -> None:
        self.min_df = min_df
        self.smooth_idf = smooth_idf
        self.idf: Dict[str, float] = {}
        self._n_docs = 0

    @staticmethod
    def _terms(text: str) -> Counter:
        return Counter(re.findall(r"[a-z0-9]+", text.lower()))

    def fit(self, documents: Iterable[Any]) -> "TfidfEmbedder":
        """Fit IDF weights on documents/chunks (any object with ``.text``)."""
        df: Counter = Counter()
        n = 0
        for doc in documents:
            df.update(set(self._terms(doc.text).keys()))
            n += 1
        self._n_docs = n
        for term, freq in df.items():
            if freq < self.min_df:
                continue
            denom = freq + 1
            if self.smooth_idf:
                self.idf[term] = math.log((n + 1) / denom) + 1.0
            else:
                self.idf[term] = math.log(n / denom) + 1.0
        return self

    def embed(self, text: str) -> Dict[str, float]:
        tf = self._terms(text)
        vec: Dict[str, float] = {}
        if tf and self.idf:
            for term, count in tf.items():
                if term in self.idf:
                    vec[term] = count * self.idf[term]
        return l2_normalize(vec)  # type: ignore[return-value]


# ---------------------------------------------------------------------------
# Metadata filtering
# ---------------------------------------------------------------------------

_DATE_RE = re.compile(
    r"^\d{4}-\d{2}-\d{2}"
    r"(?:[T ]\d{2}:\d{2}(?::\d{2}(?:\.\d+)?)?(?:Z|[+-]\d{2}:?\d{2})?)?$"
)


def _coerce_date(value: Any) -> Any:
    """Parse ISO-ish date strings so range operators work on dates."""
    if isinstance(value, (datetime, date)):
        return value
    if isinstance(value, str) and _DATE_RE.match(value):
        try:
            return datetime.fromisoformat(value.replace("Z", "+00:00"))
        except ValueError:
            return value
    return value


def _coerce(value: Any) -> Any:
    """Coerce scalar strings to bool/int/float where possible."""
    if isinstance(value, str):
        low = value.lower()
        if low in ("true", "false"):
            return low == "true"
        if low in ("none", "null"):
            return None
        try:
            return int(value)
        except ValueError:
            pass
        try:
            return float(value)
        except ValueError:
            pass
    return value


def _compare(left: Any, op: str, right: Any) -> bool:
    left_c, right_c = _coerce_date(left), _coerce_date(right)
    try:
        if op == "gt":
            return left_c > right_c
        if op == "gte":
            return left_c >= right_c
        if op == "lt":
            return left_c < right_c
        if op == "lte":
            return left_c <= right_c
    except TypeError:
        return False
    return False


def match_condition(meta_value: Any, condition: Any) -> bool:
    """Evaluate one metadata condition against a chunk's metadata value.

    Supported operators (``$`` prefix optional): ``eq``, ``ne``, ``in``,
    ``nin``, ``contains``, ``range``, ``gt``, ``gte``, ``lt``, ``lte``,
    ``regex``, ``exists``. A bare non-dict condition is shorthand equality.
    """
    if isinstance(condition, dict):
        for op, val in condition.items():
            op = op.lstrip("$").lower()
            if op in ("eq", "equals", "=="):
                if _coerce(meta_value) != _coerce(val):
                    return False
            elif op in ("ne", "neq", "!="):
                if _coerce(meta_value) == _coerce(val):
                    return False
            elif op == "in":
                allowed = val if isinstance(val, (list, tuple, set)) else [val]
                if meta_value not in allowed:
                    return False
            elif op in ("nin", "not_in"):
                forbidden = val if isinstance(val, (list, tuple, set)) else [val]
                if meta_value in forbidden:
                    return False
            elif op in ("contains", "has"):
                if isinstance(meta_value, (list, tuple, set)):
                    if val not in meta_value:
                        return False
                elif isinstance(meta_value, str):
                    if str(val) not in meta_value:
                        return False
                else:
                    return False
            elif op == "range":
                lo, hi = val
                if not (meta_value >= lo and meta_value <= hi):
                    return False
            elif op in ("gt", "gte", "lt", "lte"):
                if not _compare(meta_value, op, val):
                    return False
            elif op in ("regex", "matches"):
                if not isinstance(meta_value, str) or not re.search(str(val), meta_value):
                    return False
            elif op == "exists":
                present = meta_value is not None and meta_value != ""
                if bool(val) != present:
                    return False
            else:
                raise ValueError(f"Unsupported filter operator: {op}")
        return True
    return _coerce(meta_value) == _coerce(condition)


def chunk_matches_filters(chunk: Chunk, filters: Mapping[str, Any]) -> bool:
    """True when a chunk satisfies every key/condition in ``filters``."""
    for key, condition in filters.items():
        if key not in chunk.metadata:
            if isinstance(condition, dict) and condition.get("exists") is False:
                continue
            return False
        if not match_condition(chunk.metadata[key], condition):
            return False
    return True


# ---------------------------------------------------------------------------
# Vector store
# ---------------------------------------------------------------------------


class MetadataVectorStore:
    """In-memory vector store of chunks with metadata.

    ``search`` first narrows the candidate set with metadata filters, then
    scores candidates by cosine similarity to the query embedding. An
    inverted index over scalar/list metadata values accelerates exact
    ``eq``/``in`` filters.
    """

    def __init__(self, embedder: Any) -> None:
        self.embedder = embedder
        self.chunks: List[Chunk] = []
        self.vectors: List[Vector] = []
        self._index_by_key: Dict[str, Dict[Any, List[int]]] = {}

    def add_chunks(self, chunks: Sequence[Chunk]) -> None:
        for chunk in chunks:
            self.chunks.append(chunk)
            self.vectors.append(self.embedder.embed(chunk.text))
        self._reindex()

    def add_documents(
        self, documents: Sequence[Document], chunker: RecursiveChunker
    ) -> int:
        chunks = chunk_documents(documents, chunker)
        self.add_chunks(chunks)
        return len(chunks)

    def _reindex(self) -> None:
        self._index_by_key.clear()
        for i, chunk in enumerate(self.chunks):
            for key, value in chunk.metadata.items():
                if isinstance(value, (list, tuple, set)):
                    for v in value:
                        self._index_by_key.setdefault(key, {}).setdefault(
                            _coerce(v), []
                        ).append(i)
                else:
                    self._index_by_key.setdefault(key, {}).setdefault(
                        _coerce(value), []
                    ).append(i)

    def filter_candidate_ids(self, filters: Mapping[str, Any]) -> List[int]:
        """Return chunk indices passing all metadata filters."""
        if not filters:
            return list(range(len(self.chunks)))
        ids: Optional[List[int]] = None
        pending: Dict[str, Any] = {}
        for key, condition in filters.items():
            index = self._index_by_key.get(key)
            if (
                index is not None
                and isinstance(condition, dict)
                and set(condition.keys()) <= {"in", "eq"}
            ):
                wanted: List[Any] = []
                for op, val in condition.items():
                    vals = val if isinstance(val, (list, tuple, set)) else [val]
                    wanted.extend(vals)
                hit: set = set()
                for w in wanted:
                    hit.update(index.get(_coerce(w), []))
                ids = sorted(hit) if ids is None else sorted(set(ids) & hit)
            else:
                pending[key] = condition
        if ids is None:
            ids = list(range(len(self.chunks)))
        result: List[int] = []
        for i in ids:
            chunk = self.chunks[i]
            ok = True
            for key, condition in pending.items():
                if key not in chunk.metadata:
                    if isinstance(condition, dict) and condition.get("exists") is False:
                        continue
                    ok = False
                    break
                if not match_condition(chunk.metadata[key], condition):
                    ok = False
                    break
            if ok:
                result.append(i)
        return result

    def search(
        self,
        query: str,
        k: int = 10,
        filters: Optional[Mapping[str, Any]] = None,
    ) -> List[RetrievalResult]:
        """Filter candidates by metadata, then rank by cosine similarity."""
        qv = self.embedder.embed(query)
        candidates = self.filter_candidate_ids(filters or {})
        scored = [(i, cosine_similarity(qv, self.vectors[i])) for i in candidates]
        scored.sort(key=lambda t: t[1], reverse=True)
        return [
            RetrievalResult(chunk=self.chunks[i], similarity=score)
            for i, score in scored[:k]
        ]

    def vector(self, index: int) -> Vector:
        return self.vectors[index]


# ---------------------------------------------------------------------------
# Ranking
# ---------------------------------------------------------------------------


@dataclass
class RankingWeights:
    """Relative weights of the three ranking signals (need not sum to 1)."""

    semantic: float = 0.60
    keyword: float = 0.20
    metadata: float = 0.20


@dataclass
class RankingConfig:
    """Configuration for :class:`RelevanceRanker`."""

    weights: RankingWeights = field(default_factory=RankingWeights)
    recency_halflife_days: Optional[float] = 365.0
    recency_key: str = "date"
    boost_key: str = "boost"
    use_mmr: bool = False
    mmr_lambda: float = 0.5
    fetch_multiplier: int = 3


_TOKEN_RE = re.compile(r"[a-z0-9]+")


def _tokenize(text: str) -> set:
    return set(_TOKEN_RE.findall(text.lower()))


def _keyword_coverage(query: str, text: str) -> float:
    q_tokens = _tokenize(query)
    if not q_tokens:
        return 0.0
    text_tokens = _tokenize(text)
    return len(q_tokens & text_tokens) / len(q_tokens)


def _days_since(value: Any) -> Optional[float]:
    v = _coerce_date(value)
    if isinstance(v, datetime):
        return (datetime.now() - v).total_seconds() / 86400.0
    if isinstance(v, date):
        return (date.today() - v).days
    return None


def _recency_score(days: float, halflife_days: float) -> float:
    if halflife_days <= 0:
        return 1.0
    return 0.5 ** (days / halflife_days)


class RelevanceRanker:
    """Ranks retrieval results by a weighted blend of signals.

    * **semantic** – cosine similarity between query and chunk embeddings
    * **keyword**  – fraction of query tokens appearing in the chunk text
    * **metadata** – recency decay (``date``), query-declared metadata
      preferences (``prefer``), and an explicit numeric ``boost`` that
      multiplies the base metadata score

    An optional MMR pass trades raw score for diversity.
    """

    def __init__(self, store: MetadataVectorStore, config: Optional[RankingConfig] = None) -> None:
        self.store = store
        self.config = config or RankingConfig()

    def metadata_relevance(
        self, chunk: Chunk, prefer: Mapping[str, Any]
    ) -> float:
        """Combine recency, preferences, and explicit boost into [0, 1]."""
        cfg = self.config
        parts: List[float] = []

        if cfg.recency_key and cfg.recency_halflife_days:
            days = _days_since(chunk.metadata.get(cfg.recency_key))
            if days is not None:
                parts.append(_recency_score(max(0.0, days), cfg.recency_halflife_days))

        if prefer:
            hits = 0
            for key, preferred in prefer.items():
                value = chunk.metadata.get(key)
                if isinstance(value, (list, tuple, set)):
                    hit = preferred in value
                else:
                    hit = _coerce(value) == _coerce(preferred)
                hits += 1 if hit else 0
            parts.append(hits / len(prefer))

        base = sum(parts) / len(parts) if parts else 0.0

        if cfg.boost_key:
            boost = chunk.metadata.get(cfg.boost_key)
            if isinstance(boost, (int, float)) and boost > 0:
                base = min(1.0, base * float(boost))
        return base

    def rank(
        self,
        query: str,
        results: Sequence[RetrievalResult],
        prefer: Optional[Mapping[str, Any]] = None,
    ) -> List[RankedResult]:
        w = self.config.weights
        ranked: List[RankedResult] = []
        for res in results:
            kw = _keyword_coverage(query, res.chunk.text)
            meta = self.metadata_relevance(res.chunk, prefer or {})
            final = w.semantic * res.similarity + w.keyword * kw + w.metadata * meta
            ranked.append(
                RankedResult(
                    chunk=res.chunk,
                    similarity=res.similarity,
                    keyword_score=kw,
                    metadata_score=meta,
                    final_score=final,
                )
            )
        ranked.sort(key=lambda r: r.final_score, reverse=True)
        for i, r in enumerate(ranked):
            r.rank = i + 1
        if self.config.use_mmr and len(ranked) > 1:
            ranked = self._mmr(ranked)
        return ranked

    def _mmr(self, ranked: List[RankedResult]) -> List[RankedResult]:
        """Maximal Marginal Relevance: penalise similarity to chosen items."""
        lam = self.config.mmr_lambda
        indices = {c.chunk_id: i for i, c in enumerate(self.store.chunks)}
        selected: List[RankedResult] = []
        pool = list(ranked)
        while pool:
            best_i, best_val = -1, -1.0
            for i, cand in enumerate(pool):
                sim = cand.final_score
                if selected:
                    max_dup = max(
                        self._pairwise_similarity(cand, sel, indices)
                        for sel in selected
                    )
                    sim = lam * cand.final_score - (1.0 - lam) * max_dup
                if sim > best_val:
                    best_val, best_i = sim, i
            sel = pool.pop(best_i)
            sel.rank = len(selected) + 1
            selected.append(sel)
        return selected

    def _pairwise_similarity(
        self, a: RankedResult, b: RankedResult, indices: Dict[str, int]
    ) -> float:
        ia = indices.get(a.chunk.chunk_id)
        ib = indices.get(b.chunk.chunk_id)
        if ia is None or ib is None:
            return 0.0
        return cosine_similarity(self.store.vector(ia), self.store.vector(ib))


# ---------------------------------------------------------------------------
# Generation
# ---------------------------------------------------------------------------


@dataclass
class GeneratedAnswer:
    text: str
    method: str = ""


class ExtractiveGenerator:
    """Dependency-free fallback: answers from the best-scoring sentences."""

    _SENT_RE = re.compile(r"(?<=[.!?])\s+")

    def generate(
        self,
        question: str,
        context: Sequence[RankedResult],
        max_sentences: int = 3,
    ) -> GeneratedAnswer:
        if not context:
            return GeneratedAnswer("I could not find relevant information.", "extractive")
        top = context[0]
        sentences = [s.strip() for s in self._SENT_RE.split(top.chunk.text) if s.strip()]
        if not sentences:
            return GeneratedAnswer(top.chunk.text[:500], "extractive")
        q_tokens = _tokenize(question)
        scored = []
        for s in sentences:
            s_tokens = _tokenize(s)
            overlap = len(q_tokens & s_tokens)
            scored.append((overlap / max(1, len(q_tokens)), len(s), s))
        scored.sort(key=lambda t: (-t[0], t[1]))
        picked = [s for _, _, s in scored[:max_sentences]]
        text = " ".join(picked) if picked else sentences[0]
        return GeneratedAnswer(text, "extractive")


class OpenAICompatibleGenerator:
    """Generates grounded answers through an OpenAI-compatible chat API.

    Configure with environment variables::

        OPENAI_API_KEY=<key>                  # required
        OPENAI_BASE_URL=http://host:8000/v1   # optional (OpenAI default)
        OPENAI_CHAT_MODEL=gpt-4o-mini         # optional

    On any failure :meth:`RAGPipeline.answer` falls back to the
    :class:`ExtractiveGenerator`.
    """

    def __init__(
        self,
        api_key: Optional[str] = None,
        base_url: Optional[str] = None,
        model: Optional[str] = None,
        timeout: float = 30.0,
    ) -> None:
        self.api_key = api_key or os.environ.get("OPENAI_API_KEY", "")
        self.base_url = (
            base_url
            or os.environ.get("OPENAI_BASE_URL", "https://api.openai.com/v1")
        ).rstrip("/")
        self.model = model or os.environ.get("OPENAI_CHAT_MODEL", "gpt-4o-mini")
        self.timeout = timeout

    def generate(
        self, question: str, context: Sequence[RankedResult]
    ) -> GeneratedAnswer:
        if not context:
            return GeneratedAnswer("I could not find relevant information.", "openai")
        system = (
            "You are a precise assistant. Answer the user's question using ONLY the "
            "provided context passages. Cite passages by their [chunk_id] labels. "
            "If the context does not contain the answer, say 'Not enough information'."
        )
        user_parts = ["Question: " + question, "", "Context passages:"]
        for r in context:
            user_parts.append(f"[{r.chunk.chunk_id}] (score={r.final_score:.3f}) {r.chunk.text}")
        payload = {
            "model": self.model,
            "messages": [
                {"role": "system", "content": system},
                {"role": "user", "content": "\n\n".join(user_parts)},
            ],
            "temperature": 0.2,
        }
        req = urllib.request.Request(
            self.base_url + "/chat/completions",
            data=json.dumps(payload).encode("utf-8"),
            headers={
                "Content-Type": "application/json",
                "Authorization": f"Bearer {self.api_key}",
            },
            method="POST",
        )
        with urllib.request.urlopen(req, timeout=self.timeout) as resp:
            data = json.loads(resp.read().decode("utf-8"))
        text = data["choices"][0]["message"]["content"].strip()
        return GeneratedAnswer(text, "openai")


# ---------------------------------------------------------------------------
# End-to-end pipeline
# ---------------------------------------------------------------------------


class RAGPipeline:
    """End-to-end metadata-aware RAG pipeline."""

    def __init__(
        self,
        store: MetadataVectorStore,
        ranker: RelevanceRanker,
        generator: Any = None,
    ) -> None:
        self.store = store
        self.ranker = ranker
        self.generator = generator or ExtractiveGenerator()

    @classmethod
    def from_documents(
        cls,
        documents: Sequence[Document],
        embedder: Optional[Any] = None,
        chunker: Optional[RecursiveChunker] = None,
        ranking_config: Optional[RankingConfig] = None,
        generator: Optional[Any] = None,
    ) -> "RAGPipeline":
        chunker = chunker or RecursiveChunker()
        embedder = embedder or HashedNGramEmbedder()
        if isinstance(embedder, TfidfEmbedder):
            embedder.fit(documents)
        store = MetadataVectorStore(embedder)
        store.add_documents(documents, chunker)
        ranker = RelevanceRanker(store, ranking_config or RankingConfig())
        return cls(store, ranker, generator)

    def retrieve(
        self,
        query: str,
        k: int = 5,
        filters: Optional[Mapping[str, Any]] = None,
        prefer: Optional[Mapping[str, Any]] = None,
    ) -> List[RankedResult]:
        """Retrieve and rank the top ``k`` chunks under metadata filters."""
        fetch = k * max(1, self.ranker.config.fetch_multiplier)
        raw = self.store.search(query, k=fetch, filters=filters)
        ranked = self.ranker.rank(query, raw, prefer=prefer)
        return ranked[:k]

    def answer(
        self,
        query: str,
        k: int = 5,
        filters: Optional[Mapping[str, Any]] = None,
        prefer: Optional[Mapping[str, Any]] = None,
        generate: bool = True,
    ) -> RAGResponse:
        """Run the full RAG loop: filter -> rank -> generate."""
        start = time.monotonic()
        sources = self.retrieve(query, k=k, filters=filters, prefer=prefer)
        method = "none"
        text = ""
        if generate and sources:
            try:
                gen = self.generator.generate(query, sources)
                text, method = gen.text, gen.method
            except Exception as exc:  # network / API failure fallback
                fallback = ExtractiveGenerator().generate(query, sources)
                text, method = fallback.text, f"fallback:{type(exc).__name__}"
        elif sources:
            text = "\n".join(f"[{s.rank}] {s.chunk.text}" for s in sources)
        else:
            text = "No documents matched the metadata filters."
        return RAGResponse(
            query=query,
            answer=text,
            sources=sources,
            filters=dict(filters or {}),
            elapsed_seconds=time.monotonic() - start,
            generation_method=method,
        )


